import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.CBWbbCW8.js";const u=JSON.parse('{"title":"产品介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/product.md","filePath":"guide/product.md","lastUpdated":1784967005000}'),i={name:"guide/product.md"};function r(l,t,c,n,s,h){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="产品介绍" tabindex="-1">产品介绍 <a class="header-anchor" href="#产品介绍" aria-label="Permalink to &quot;产品介绍&quot;">​</a></h1><p>DouDi.ai 是一个统一的 AI API 网关与管理控制台。它把多个上游模型和供应商整理到同一个控制台中，让用户可以通过统一的 API 地址、统一的 API Key 和统一的额度体系来使用不同模型。</p><p>根据公开站点信息，DouDi.ai 的系统名称为“兜底 | DouDi.ai”，公开导航中启用了模型广场和控制台入口。控制台侧边栏包含 API Key、调用日志、充值钱包、模型、个人资料等模块；管理员侧还包含渠道、模型管理、用户、兑换码、订阅、系统设置等模块。</p><h2 id="适合谁使用" tabindex="-1">适合谁使用 <a class="header-anchor" href="#适合谁使用" aria-label="Permalink to &quot;适合谁使用&quot;">​</a></h2><ul><li>想用一个 API Key 调用多个 AI 模型的开发者。</li><li>想把 OpenAI 兼容客户端接入统一网关的用户。</li><li>想查看模型倍率、可用分组和接口类型，再选择模型的团队。</li><li>需要记录调用日志、管理余额额度和控制 API Key 权限的使用者。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>Base URL</td><td>DouDi.ai 的 API 服务地址，公开状态接口显示为 <code>https://doudi.ai</code>。OpenAI 兼容接口通常使用 <code>https://doudi.ai/v1</code>。</td></tr><tr><td>API Key</td><td>用于鉴权的密钥。请求时放在 <code>Authorization: Bearer YOUR_API_KEY</code> 中。</td></tr><tr><td>模型</td><td>调用时传入的 <code>model</code> 字段，例如公开价格接口中出现的 <code>gpt-5.6</code>、<code>gpt-5.5</code> 等。</td></tr><tr><td>分组</td><td>平台用来区分可用池和倍率的用户组，例如公开数据中包含 <code>Codex-Stable</code>、<code>Codex-Standard</code>。</td></tr><tr><td>倍率</td><td>模型和分组的计费权重。实际消耗会受模型倍率、输出倍率、缓存倍率、用户组倍率等因素影响。</td></tr></tbody></table><h2 id="官方入口" tabindex="-1">官方入口 <a class="header-anchor" href="#官方入口" aria-label="Permalink to &quot;官方入口&quot;">​</a></h2><ul><li>控制台入口：<a href="https://doudi.ai" target="_blank" rel="noreferrer">https://doudi.ai</a></li><li>模型与价格：<a href="https://doudi.ai/pricing" target="_blank" rel="noreferrer">https://doudi.ai/pricing</a></li><li>频道/渠道页：<a href="https://doudi.ai/channels" target="_blank" rel="noreferrer">https://doudi.ai/channels</a></li><li>公开文档链接：站点状态接口当前返回 <code>https://docs.newapi.pro</code></li></ul><div class="tip custom-block"><p class="custom-block-title">说明</p><p>本文档是针对 DouDi.ai 当前公开页面和公开接口整理的使用文档，不替代平台后台中的实时配置。涉及余额、权限、可用模型时，请以登录后的控制台显示为准。</p></div>',10)])])}const _=e(i,[["render",r]]);export{u as __pageData,_ as default};
